-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-pass-through-expense-create-rpc.sql
-- Source SHA256: FB5B133AF5E51C8AD70363F98FDFF496D17AAE2ADC079C165114A40618111E22
-- Local replay required before any staging promotion.
-- OTOTR PASS-THROUGH EXPENSE CREATE RPC CANDIDATE
create or replace function finance_private.current_pass_through_expense_create_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_pass_through_expense_create_scope(p_actor_id uuid,p_legal_entity_id uuid,p_target_scopes jsonb,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_api.authorize_pass_through_expense_create(p_legal_entity_id uuid,p_target_scopes jsonb,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and p_permission='finance.expenses.create' and finance_private.resolve_pass_through_expense_create_scope(auth.uid(),p_legal_entity_id,p_target_scopes,p_permission)$$;

create or replace function finance_api.commit_pass_through_expense_create(p_actor_id uuid,p_legal_entity_id uuid,p_supplier_reference text,p_supplier_reference_normalized text,p_fee_definition_id uuid,p_expense_date date,p_currency_code text,p_net_amount numeric,p_tax_amount numeric,p_gross_amount numeric,p_contractual_basis_reference text,p_document_ids uuid[],p_target_scopes jsonb,p_note_hash text,p_idempotency_key text,p_input_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare v_id uuid:=gen_random_uuid();v_existing finance.pass_through_expenses%rowtype;v_evidence_hash text;v_document_count integer;v_scope_count integer;v_payload jsonb;v_previous text;v_audit text;v_supplier_hash text;
begin
 if not finance_private.current_pass_through_expense_create_committer_is_trusted() then raise exception using errcode='42501',message='trusted pass through expense create committer required';end if;
 if pg_catalog.length(pg_catalog.btrim(coalesce(p_supplier_reference,''))) not between 1 and 200 or pg_catalog.length(pg_catalog.btrim(coalesce(p_supplier_reference_normalized,''))) not between 1 and 200 or pg_catalog.length(pg_catalog.btrim(coalesce(p_contractual_basis_reference,''))) not between 1 and 200 then raise exception using errcode='22023',message='expense references invalid';end if;
 if p_currency_code!~'^[A-Z]{3}$' or p_net_amount<0 or p_tax_amount<0 or p_gross_amount<0 or p_gross_amount<>p_net_amount+p_tax_amount then raise exception using errcode='23514',message='expense totals invalid';end if;
 if pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_input_hash!~'^[a-fA-F0-9]{64}$' or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') then raise exception using errcode='22023',message='expense integrity fields invalid';end if;
 if p_document_ids is null or pg_catalog.cardinality(p_document_ids)<1 or pg_catalog.cardinality(p_document_ids)<>(select pg_catalog.count(distinct x) from pg_catalog.unnest(p_document_ids) x) then raise exception using errcode='22023',message='expense documents must be nonempty and unique';end if;
 if pg_catalog.jsonb_typeof(p_target_scopes)<>'array' or pg_catalog.jsonb_array_length(p_target_scopes)<1 or exists(select 1 from pg_catalog.jsonb_array_elements(p_target_scopes) s where pg_catalog.jsonb_typeof(s)<>'object' or (select pg_catalog.array_agg(k order by k) from pg_catalog.jsonb_object_keys(s) k) is distinct from array['branchId','dealerAccountId']::text[] or coalesce(s->>'branchId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(s->>'dealerAccountId','')!~'^[0-9a-fA-F-]{36}$') then raise exception using errcode='22023',message='expense target scopes invalid';end if;
 select pg_catalog.count(*) into v_scope_count from (select distinct s->>'dealerAccountId' da,s->>'branchId' br from pg_catalog.jsonb_array_elements(p_target_scopes) s) q;if v_scope_count<>pg_catalog.jsonb_array_length(p_target_scopes) then raise exception using errcode='22023',message='expense target scopes must be unique';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('expense-create:'||p_legal_entity_id::text||':'||p_idempotency_key,0));
 select * into v_existing from finance.pass_through_expenses e where e.legal_entity_id=p_legal_entity_id and e.idempotency_key=p_idempotency_key for update;if found then if v_existing.input_hash=p_input_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','expenseId',v_existing.id,'status',v_existing.status,'inputHash',v_existing.input_hash,'version',v_existing.version);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if exists(select 1 from finance.pass_through_expenses e where e.legal_entity_id=p_legal_entity_id and e.supplier_reference_normalized=p_supplier_reference_normalized) then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.fee_definitions fd where fd.id=p_fee_definition_id and fd.status='PUBLISHED' and fd.fee_family='PASS_THROUGH_EXPENSE' and (fd.legal_entity_id is null or fd.legal_entity_id=p_legal_entity_id)) then raise exception using errcode='23514',message='published pass through expense fee definition required';end if;
 if exists(select 1 from pg_catalog.jsonb_array_elements(p_target_scopes) s where not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=(s->>'dealerAccountId')::uuid and b.id=(s->>'branchId')::uuid and da.legal_entity_id=p_legal_entity_id and da.status='ACTIVE' and b.status='ACTIVE' and da.currency_code=p_currency_code)) then raise exception using errcode='42501',message='expense target branch scope denied';end if;
 select pg_catalog.count(*),pg_catalog.encode(extensions.digest(pg_catalog.convert_to(pg_catalog.string_agg(dr.external_document_id::text||':'||dr.content_hash,'|' order by dr.external_document_id),'UTF8'),'sha256'),'hex') into v_document_count,v_evidence_hash from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.external_document_id=any(p_document_ids) and dr.status='ACTIVE';if v_document_count<>pg_catalog.cardinality(p_document_ids) then raise exception using errcode='23514',message='all expense documents must be active in legal entity';end if;
 insert into finance.pass_through_expenses(id,legal_entity_id,fee_definition_id,supplier_reference,supplier_reference_normalized,contractual_basis_reference,expense_date,currency_code,source_net_amount,source_tax_amount,source_amount,distributable_net_amount,distributable_tax_amount,distributable_amount,allocation_policy,evidence_object_key,evidence_hash,idempotency_key,input_hash,note_hash,status,prepared_by,version,created_by,correlation_id) values(v_id,p_legal_entity_id,p_fee_definition_id,p_supplier_reference,p_supplier_reference_normalized,p_contractual_basis_reference,p_expense_date,p_currency_code,p_net_amount,p_tax_amount,p_gross_amount,p_net_amount,p_tax_amount,p_gross_amount,pg_catalog.jsonb_build_object('status','UNDECIDED','targetScopes',p_target_scopes),'DOCUMENT_LINKS:'||v_evidence_hash,v_evidence_hash,p_idempotency_key,p_input_hash,p_note_hash,'DRAFT',p_actor_id,1,p_actor_id,p_correlation_id);
 insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) select p_legal_entity_id,dr.id,'PASS_THROUGH_EXPENSE',v_id,'SOURCE_EVIDENCE_V1',p_actor_id,p_correlation_id from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.external_document_id=any(p_document_ids) order by dr.external_document_id;
 v_payload:=pg_catalog.jsonb_build_object('expenseId',v_id,'feeDefinitionId',p_fee_definition_id,'status','DRAFT','inputHash',p_input_hash,'idempotencyKey',p_idempotency_key,'documentCount',v_document_count,'targetScopeCount',v_scope_count);insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.expense','PASS_THROUGH_EXPENSE_DRAFT_CREATED','PASS_THROUGH_EXPENSE',v_id,1,v_payload,p_input_hash,'PENDING',p_correlation_id);
 v_supplier_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_supplier_reference_normalized,'UTF8'),'sha256'),'hex');perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v_id::text||':PASS_THROUGH_EXPENSE_DRAFT_CREATED:'||p_input_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','PASS_THROUGH_EXPENSE_DRAFT_CREATED','PASS_THROUGH_EXPENSE',v_id,'ALLOW',p_input_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('feeDefinitionId',p_fee_definition_id,'supplierReferenceHash',v_supplier_hash,'documentCount',v_document_count,'targetScopeCount',v_scope_count),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','CREATED','expenseId',v_id,'status','DRAFT','inputHash',p_input_hash,'version',1);
end$$;

revoke all on function finance_private.current_pass_through_expense_create_committer_is_trusted() from public,anon,authenticated;
revoke all on function finance_private.resolve_pass_through_expense_create_scope(uuid,uuid,jsonb,text) from public,anon,authenticated;
revoke all on function finance_api.authorize_pass_through_expense_create(uuid,jsonb,text) from public,anon;
grant execute on function finance_api.authorize_pass_through_expense_create(uuid,jsonb,text) to authenticated;
revoke all on function finance_api.commit_pass_through_expense_create(uuid,uuid,text,text,uuid,date,text,numeric,numeric,numeric,text,uuid[],jsonb,text,text,text,uuid) from public,anon,authenticated;
